import numpy as np
from itertools import combinations, product

def test_exact_search(N, num_trials=200):
    all_combos = list(combinations(range(40), 3))
    signs = list(product([-1, 1], repeat=3))

    unique_success = 0
    for _ in range(num_trials):
        true_supp = tuple(sorted(np.random.choice(40, 3, replace=False)))
        true_signs = tuple(np.random.choice([-1, 1], 3))

        X = np.random.choice([-1, 1], size=(N, 40))
        z = sum(s * X[:, i] for i, s in zip(true_supp, true_signs))
        y = (z > 0).astype(int)

        # Check how many (supp, signs) have 0 errors on (X, y)
        zero_err_count = 0
        for supp in all_combos:
            X_sub = X[:, supp]
            for s in signs:
                pred = ((X_sub @ np.array(s)) > 0).astype(int)
                if np.array_equal(pred, y):
                    zero_err_count += 1
                    if zero_err_count > 1:
                        break
            if zero_err_count > 1:
                break
        if zero_err_count == 1:
            unique_success += 1

    return unique_success / num_trials

for N in [30, 40, 50, 60]:
    print(f"N={N}: unique 0-error rule = {test_exact_search(N, 50)}")

